// The optimization scoreboard. Every IR/codegen transform is judged here
// before it earns a default:
//   - dynamic IR ops: bin/un/select nodes executed for the benchmark
//     paragraph (JIT-independent; the primary measure for IR transforms)
//   - static ops / generated bytes: code size and inspectability
//   - wall clock: median paragraph raster time (secondary; JIT-laundered)
// plus a hard gate: every variant must produce span-identical output.
//
// Run: npm run bench

import { compileLibraryFile } from '../src/sources.js';
import { renderText } from '../src/text/render.js';
import type { CompileOptions } from '../../umgeni/src/compile.js';
import { kernelOpCount } from '../../umgeni/src/ir.js';

const TEXT =
  'THE QUICK BROWN FOX JUMPS OVER THE LAZY DOG. PACK MY BOX WITH FIVE DOZEN JUGS. ' +
  'UMGENI RENDERS THIS PARAGRAPH THROUGH A PIPELINE COMPILED FROM NILE SOURCE, WRAPPING LINES AS IT GOES.';
const OPTS = { size: 18, width: 880, height: 360, margin: 8 };


interface Variant {
  name: string;
  opts: CompileOptions;
}
const VARIANTS: Variant[] = [
  { name: 'baseline', opts: { cse: false, boolCond: false, fuse: false, tail: false } },
  { name: '+cse', opts: { cse: true, boolCond: false, fuse: false } },
  { name: '+bool', opts: { cse: false, boolCond: true, fuse: false } },
  { name: '+cse +bool', opts: { cse: true, boolCond: true, fuse: false } },
  { name: '+fuse', opts: { cse: false, boolCond: false, fuse: true } },
  { name: 'all -tail', opts: { cse: true, boolCond: true, fuse: true, tail: false } },
  { name: 'all four', opts: { cse: true, boolCond: true, fuse: true } },
  // Fused segments as WebAssembly (op counting is a JS-codegen feature).
  { name: 'all + wasm', opts: { cse: true, boolCond: true, fuse: true, target: 'wasm' } },
];

function median(xs: number[]): number {
  const s = [...xs].sort((a, b) => a - b);
  return s[Math.floor(s.length / 2)];
}

let referenceSpans: string | null = null;

console.log(`paragraph: ${TEXT.length} chars @ ${OPTS.size}px, ${OPTS.width}x${OPTS.height}`);
console.log('variant     | dyn ops     | static ops | gen bytes | raster ms (median of 15)');
console.log('------------|-------------|------------|-----------|-------------------------');
for (const v of VARIANTS) {
  // Instrumented build for the op counts (never timed).
  const wasm = v.opts.target === 'wasm';
  const counted = compileLibraryFile('demos/nl/text.nl-lib', { ...v.opts, countOps: !wasm });
  const before = wasm ? 0 : counted.ops!();
  const { spans } = renderText(counted, TEXT, OPTS);
  const dynOps = wasm ? '—' : counted.ops!() - before;

  // Output-equality gate against the baseline.
  const sig = JSON.stringify(spans);
  if (referenceSpans === null) referenceSpans = sig;
  else if (sig !== referenceSpans) throw new Error(`variant '${v.name}' changed the output!`);

  // Clean build for size and time.
  const library = compileLibraryFile('demos/nl/text.nl-lib', v.opts);
  const stat = library.ir.processes.reduce((n, p) => n + (p.k === 'kernel' ? kernelOpCount(p) : 0), 0);
  for (let i = 0; i < 5; i++) renderText(library, TEXT, OPTS); // warm-up
  const times = Array.from({ length: 15 }, () => renderText(library, TEXT, OPTS).rasterMs);

  console.log(
    `${v.name.padEnd(11)} | ${String(dynOps).padStart(11)} | ${String(stat).padStart(10)} | ` +
    `${String(library.source.length).padStart(9)} | ${median(times).toFixed(2)}`,
  );
}
console.log('output-equality gate: all variants span-identical ✓');
